        std::sort(videos.begin(), videos.end(), [](const Video& a, const Video& b) { return a.title < b.title; });
    } else if (sort == "date") {
        std::sort(videos.begin(), videos.end(), [](const Video& a, const Video& b) { return a.date < b.date; });
    }
    return videos;
}

