void sortResults(std::vector<std::string>& results, std::string sortBy) {
   for (int i = 0; i < results.size(); i++) {
       for (int j = i + 1; j < results.size(); j++) {
           if (sortBy == "asc") {
               if (results[i] > results[j]) {
                   std::swap(results[i], results[j]);
               }
           } else if (sortBy == "desc") {
               if (results[i] < results[j]) {
                   std::swap(results[i], results[j]);
               }
           }
       }
   }
}

