  double total_amount = 0;
  for (auto& claim : claims) {
    if (claim.is_clean()) {
      total_amount += claim.get_amount();
    }
  }
  for (auto& provider : providers) {
    provider.add_clean_claim(total_amount);
  }
  return total_amount;
}

