std::map<Product, int> cart;

void add_to_cart(Product product, int quantity) {
  if (cart.find(product) == cart.end()) {
    cart[product] = quantity;
  } else {
    cart[product] += quantity;
  }

  double total = 0;
  for (auto& item : cart) {
    total += item.first.price * item.second;
  }

  cart_total = total;
}

void remove_from_cart(Product product) {
   if (cart.find(product) != cart.end()) {
     cart.erase(product);
   }

   double total = 0;
   for (auto& item : cart) {
     total += item.first.price * item.second;
   }

   cart_total = total;
}

